type Line struct {
	Price   int64
	Qty     int64
	Taxable bool
}

func Calculate(lines []Line, discountBP int64, taxBP int64) int64 {
	var discountedSubtotal int64
	var taxableSubtotal int64

	for _, line := range lines {
		if line.Qty <= 0 || line.Price <= 0 {
			continue
		}

		lineTotal := line.Price * line.Qty
		// Apply discount: amount * (10000 - discountBP) / 10000
		// We need to round each line after discount: (val * (10000 - discountBP) + 5000) / 10000
		// However, the formula provided is (numerator + 5000) / 10000.
		// To apply this to the discounted amount:
		// numerator = lineTotal * (10000 - discountBP)

		num := lineTotal * (10000 - discountBP)
		discountedLine := (num + 5000) / 10000

		discountedSubtotal += discountedLine
		if line.Taxable {
			taxableSubtotal += discountedLine
		}
	}

	// Compute tax from the DISCOUNTED taxable subtotal
	// Tax = taxableSubtotal * taxBP / 10000
	// Round once: (taxableSubtotal * taxBP + 5000) / 10000
	taxAmount := (taxableSubtotal*taxBP + 5000) / 10000

	return discountedSubtotal + taxAmount
}
